 * array is inside the kept span. Callers must pass keepLo <= keepHi.
 */
export function keepPieceRange(context is Context, id is Id, pieces is array, keepLo is number, keepHi is number)
{
    var discard = [];
    for (var i = 0; i < size(pieces); i += 1)
    {
